+		{Name: dep, RepoURL: depRepo},
+	}, &PluginIndex{})
+	if err != nil {
+		t.Fatalf("PlanDependencyInstalls (no minimum): %v", err)
+	}
+	if len(plan.Actions) != 0 {
+		t.Errorf("no-minimum actions = %+v, want none", plan.Actions)
+	}
