1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"os/exec"
9		"regexp"
10		"sort"
11		"strings"
12	
13		"golang.org/x/mod/semver"
14	)
15	
16	// Host-agnostic remote inspection over the git protocol. Version listing
17	// uses `git ls-remote --tags`, which behaves identically on GitHub, GitLab,
18	// Gitea/Forgejo, and any self-hosted server, inherits the user's existing
19	// git auth (SSH agent, credential helpers), and needs no forge REST client.
20	// The shell-out (vs go-git) is deliberate: this path needs the user's
21	// credential helpers and proxy config, the same reason hooks.go shells out
22	// for network-touching operations.
23	
24	// gitQuiet returns an exec.Cmd for git with terminal prompts disabled, so
25	// an auth-requiring remote fails fast instead of hanging a non-interactive
26	// run on a username prompt.
27	func gitQuiet(ctx context.Context, args ...string) *exec.Cmd {
28		cmd := exec.CommandContext(ctx, "git", args...)
29		cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
30		return cmd
31	}
32	
33	// pluginRepoURLSchemes are the transports a plugin (or index) repository URL
34	// may use. Mirrors settings.PluginSettings.Validate's allowlist, plus the
35	// git:// and http:// transports the release-asset path already accepts.
36	var pluginRepoURLSchemes = []string{"https://", "http://", "ssh://", "git://", "file://"}
37	
38	// scpLikeGitURL matches git's scp-like syntax (user@host:path) — the form
39	// `git@github.com:owner/repo.git` uses. Requires a user@, a host without a
40	// slash, and a colon before the path, so it can't match a bare option or a
41	// local path.
42	var scpLikeGitURL = regexp.MustCompile(`^[A-Za-z0-9._~-]+@[A-Za-z0-9._-]+:[^\s]`)
43	
44	// validatePluginRepoURL rejects anything that isn't recognizably a git
45	// repository URL before it reaches the git CLI as a positional argument.
46	//
47	// This is a security boundary, not a nicety. Repo URLs arrive from
48	// attacker-influenced places — index.json entries, another plugin's
49	// entire-plugin.yml `requires`, a stored manifest — and git parses an
50	// option-shaped positional as an option. `--upload-pack=<cmd>` is
51	// shell-interpreted and runs against the *ambient* repo when no positional
52	// remains, so an entry like "--upload-pack=curl … | sh; git-upload-pack"
53	// would execute arbitrary commands during an index-resolved install, which
54	// never prompts. validatePluginName already refuses a leading '-' on names
55	// for the same reason; URLs need the same treatment.
56	//
57	// Callers additionally pass "--" before positionals (defense in depth), so
58	// an option-shaped value would be rejected by git even if it got this far.
59	func validatePluginRepoURL(rawURL string) error {
60		u := strings.TrimSpace(rawURL)
61		if u == "" {
62			return errors.New("repository URL is empty")
63		}
64		if strings.HasPrefix(u, "-") {
65			return fmt.Errorf("repository URL %q must not start with '-'", rawURL)
66		}
67		for _, scheme := range pluginRepoURLSchemes {
68			if strings.HasPrefix(u, scheme) && len(u) > len(scheme) {
69				return nil
70			}
71		}
72		if scpLikeGitURL.MatchString(u) {
73			return nil
74		}
75		// An absolute local path is a valid git remote and can't be read as an
76		// option, so it stays accepted — `--index /srv/plugin-index` and
77		// bare-path test fixtures keep working. Relative paths and bare names
78		// are still rejected: they'd be ambiguous with plugin names.
79		if isAbsoluteGitPath(u) {
80			return nil
81		}
82		return fmt.Errorf("repository URL %q must be an absolute path or use one of %s or git's user@host:path form",
83			rawURL, strings.Join(pluginRepoURLSchemes, ", "))
84	}
85	
86	// isAbsoluteGitPath reports whether u is an absolute filesystem path: a
87	// leading separator, or a Windows drive prefix like C:\ or C:/.
88	func isAbsoluteGitPath(u string) bool {
89		if strings.HasPrefix(u, "/") || strings.HasPrefix(u, `\\`) {
90			return true
91		}
92		return len(u) >= 3 && u[1] == ':' &&
93			(u[2] == '/' || u[2] == '\\') &&
94			((u[0] >= 'A' && u[0] <= 'Z') || (u[0] >= 'a' && u[0] <= 'z'))
95	}
96	
97	// listRemoteSemverTags returns the repo's semver tags ("v"-prefixed or
98	// bare), sorted descending by semantic version. Non-semver tags are
99	// ignored.
100	func listRemoteSemverTags(ctx context.Context, repoURL string) ([]string, error) {
101		if err := validatePluginRepoURL(repoURL); err != nil {
102			return nil, err
103		}
104		// --refs suppresses peeled ^{} entries for annotated tags. "--" keeps an
105		// option-shaped URL from being parsed as a git option.
106		out, err := gitQuiet(ctx, "ls-remote", "--tags", "--refs", "--", repoURL).Output()
107		if err != nil {
108			return nil, fmt.Errorf("list tags of %s: %w%s", repoURL, err, stderrSuffix(err))
109		}
110		var tags []string
111		for _, line := range strings.Split(string(out), "\n") {
112			fields := strings.Fields(line)
113			if len(fields) != 2 {
114				continue
115			}
116			tag := strings.TrimPrefix(fields[1], "refs/tags/")
117			if semver.IsValid(canonicalSemver(tag)) {
118				tags = append(tags, tag)
119			}
120		}
121		sort.Slice(tags, func(i, j int) bool {
122			return semver.Compare(canonicalSemver(tags[i]), canonicalSemver(tags[j])) > 0
123		})
124		return tags, nil
125	}
126	
127	// canonicalSemver maps a tag to the "v"-prefixed form x/mod/semver expects.
128	func canonicalSemver(tag string) string {
129		if strings.HasPrefix(tag, "v") {
130			return tag
131		}
132		return "v" + tag
133	}
134	
135	// stderrSuffix extracts captured stderr from an exec.ExitError for error
136	// messages; git's stderr is where the actionable detail lives. Only
137	// populated when the command was started via Output().
138	func stderrSuffix(err error) string {
139		var exitErr *exec.ExitError
140		if errors.As(err, &exitErr) && len(exitErr.Stderr) > 0 {
141			return ": " + strings.TrimSpace(string(exitErr.Stderr))
142		}
143		return ""
144	}
145	
146	// fetchPluginMetadataAtTag reads entire-plugin.yml at the given tag without
147	// a user-visible clone: a blobless shallow clone into a discarded temp dir,
148	// falling back to a plain shallow clone for servers that don't allow
149	// partial-clone filters (uploadpack.allowFilter defaults to off outside the
150	// big forges). Returns (nil, nil) when the repo has no metadata file —
151	// metadata is optional by design.
152	func fetchPluginMetadataAtTag(ctx context.Context, repoURL, tag string) (*PluginMetadata, error) {
153		if err := validatePluginRepoURL(repoURL); err != nil {
154			return nil, err
155		}
156		tmp, err := os.MkdirTemp("", "entire-plugin-meta-")
157		if err != nil {
158			return nil, fmt.Errorf("create temp dir: %w", err)
159		}
160		defer os.RemoveAll(tmp)
161	
162		cloneArgs := func(filter bool) []string {
163			args := []string{"clone", "--depth", "1", "--no-checkout", "--branch", tag, "--quiet"}
164			if filter {
165				args = append(args, "--filter=blob:none")
166			}
167			// "--" so an option-shaped URL can't be parsed as a git option.
168			return append(args, "--", repoURL, tmp)
169		}
170		// Output() (not Run()) so stderr is captured into the ExitError for
171		// error messages; clone --quiet writes nothing to stdout.
172		if _, err := gitQuiet(ctx, cloneArgs(true)...).Output(); err != nil {
173			// Retry without the filter; the clone dir may be half-created.
174			if rmErr := os.RemoveAll(tmp); rmErr != nil {
175				return nil, fmt.Errorf("clean temp clone dir: %w", rmErr)
176			}
177			if _, err := gitQuiet(ctx, cloneArgs(false)...).Output(); err != nil {
178				return nil, fmt.Errorf("clone %s at %s: %w%s", repoURL, tag, err, stderrSuffix(err))
179			}
180		}
181		// `git show <rev>:<path>` peels annotated tags and, in a blobless
182		// clone, lazily fetches just this one blob from the promisor remote.
183		out, err := gitQuiet(ctx, "-C", tmp, "show", tag+":"+pluginMetadataFileName).Output()
184		if err != nil {
185			// Missing file and missing tag both surface as exit 128; only the
186			// missing-file case is benign. Disambiguate via stderr.
187			if strings.Contains(stderrSuffix(err), "does not exist") ||
188				strings.Contains(stderrSuffix(err), "exists on disk, but not in") {
189				return nil, nil //nolint:nilnil // metadata is optional
190			}
191			return nil, fmt.Errorf("read %s at %s: %w%s", pluginMetadataFileName, tag, err, stderrSuffix(err))
192		}
193		return ParsePluginMetadata(out)
194	}
195	
196	// pluginNameFromRepoURL derives the bare plugin name from a repository URL
197	// basename: .../entire-run(.git) → "run". Used when entire-plugin.yml is
198	// absent or doesn't declare a name.
199	func pluginNameFromRepoURL(repoURL string) (string, error) {
200		trimmed := strings.TrimSuffix(strings.TrimSuffix(repoURL, "/"), ".git")
201		base := trimmed
202		if i := strings.LastIndexAny(trimmed, "/:"); i >= 0 {
203			base = trimmed[i+1:]
204		}
205		if !strings.HasPrefix(base, pluginBinaryPrefix) {
206			return "", fmt.Errorf("repository basename %q does not start with %q; declare a name in %s", base, pluginBinaryPrefix, pluginMetadataFileName)
207		}
208		name := strings.TrimPrefix(base, pluginBinaryPrefix)
209		if err := validatePluginName(name); err != nil {
210			return "", err
211		}
