1	package cli
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"runtime"
10		"sort"
11		"time"
12	
13		"gopkg.in/yaml.v3"
14	)
15	
16	// Managed-install manifests. A plugin installed from a remote repository
17	// gets a per-plugin home under the managed dir:
18	//
19	//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
20	//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
21	//
22	// The bin/ dir remains the only dispatch surface — pkg/ binaries are
23	// linked into bin/ via the same symlink→hardlink→copy fallback as local
24	// installs, so the kubectl-style resolver in plugin.go never changes.
25	//
26	// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
27	// and have no manifest; ListPluginManifests simply doesn't see them.
28	const (
29		pluginManagedPkgSubdir = "pkg"
30		pluginManifestFileName = "manifest.yml"
31		// windowsExeExt is the extension Windows executables need.
32		windowsExeExt = ".exe"
33	)
34	
35	// pluginBinaryName returns the on-disk executable name for a bare plugin
36	// name: entire-<name>, plus the Windows extension where the host needs it.
37	func pluginBinaryName(name string) string {
38		if runtime.GOOS == windowsGOOS {
39			return pluginBinaryPrefix + name + windowsExeExt
40		}
41		return pluginBinaryPrefix + name
42	}
43	
44	// PluginManifest records how a managed plugin was installed. Settings
45	// configure behavior; manifests record facts. The dependency list is
46	// copied from the plugin's metadata at install time so reverse-dependency
47	// checks (remove guard, doctor) work offline.
48	type PluginManifest struct {
49		// Name is the bare plugin name ("run" for entire-run).
50		Name string `yaml:"name"`
51		// RepoURL is the full git URL the plugin was installed from.
52		RepoURL string `yaml:"repo_url"`
53		// Tag is the git tag that was installed (e.g. "v0.2.1").
54		Tag string `yaml:"tag"`
55		// Asset is the release asset filename the binary came from. Empty for
56		// raw-binary downloads where the asset name equals the binary name.
57		Asset string `yaml:"asset,omitempty"`
58		// SHA256 is the hex digest of the downloaded asset.
59		SHA256 string `yaml:"sha256,omitempty"`
60		// BinarySHA256 is the hex digest of the installed binary under
61		// pkg/<name>/. Distinct from SHA256, which covers the downloaded asset —
62		// usually an archive, and discarded with the staging dir. Recording the
63		// binary is what lets `plugin doctor` detect post-install tampering.
64		BinarySHA256 string `yaml:"binary_sha256,omitempty"`
65		// Unverified records that no checksum manifest authenticated the
66		// download (installed with --allow-unverified). Surfaced by doctor.
67		Unverified bool `yaml:"unverified,omitempty"`
68		// Pinned marks installs done with --pin; upgrade skips them.
69		Pinned bool `yaml:"pinned,omitempty"`
70		// InstalledAt is when the install (or last upgrade) completed.
71		InstalledAt time.Time `yaml:"installed_at,omitempty"`
72		// Requires is the dependency list from the plugin's entire-plugin.yml
73		// at the installed tag.
74		Requires []PluginRequirement `yaml:"requires,omitempty"`
75	}
76	
77	// PluginRequirement declares a dependency on another plugin. Shared between
78	// the author-side metadata file (entire-plugin.yml) and the install-side
79	// manifest so the two can never drift.
80	type PluginRequirement struct {
81		// Name is the bare plugin name of the dependency.
82		Name string `yaml:"name"`
83		// RepoURL is where to install the dependency from when it's missing.
84		// Optional when the dependency is resolvable through the index.
85		RepoURL string `yaml:"repo_url,omitempty"`
86		// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
87		// only — there is deliberately no range syntax.
88		MinVersion string `yaml:"min_version,omitempty"`
89	}
90	
91	// PluginMetadata is the author-side declaration committed at the root of a
92	// plugin repository as entire-plugin.yml. Everything is optional — a repo
93	// without the file installs fine; the name then derives from the repo URL.
94	type PluginMetadata struct {
95		// Name is the bare plugin name. When empty, derived from the repo URL
96		// basename (entire-run → run).
97		Name string `yaml:"name,omitempty"`
98		// Description is a one-line summary shown by info/search.
99		Description string `yaml:"description,omitempty"`
100		// DownloadURL overrides the per-forge release-asset URL convention.
101		// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
102		// When {asset} is present, candidate asset filenames are substituted;
103		// otherwise the expanded template is fetched as-is.
104		DownloadURL string `yaml:"download_url,omitempty"`
105		// Requires lists plugins this plugin needs at runtime.
106		Requires []PluginRequirement `yaml:"requires,omitempty"`
107	}
108	
109	// pluginMetadataFileName is the well-known path of the author-side metadata
110	// file at the root of a plugin repository.
111	const pluginMetadataFileName = "entire-plugin.yml"
112	
113	// ParsePluginMetadata decodes entire-plugin.yml content. Strict decoding:
114	// unknown keys are an error, surfacing author typos at install time rather
115	// than silently ignoring a misspelled "requires".
116	func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
117		var meta PluginMetadata
118		dec := yaml.NewDecoder(bytes.NewReader(data))
119		dec.KnownFields(true)
120		if err := dec.Decode(&meta); err != nil {
121			return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
122		}
123		if meta.Name != "" {
124			if err := validatePluginName(meta.Name); err != nil {
125				return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
126			}
127		}
128		for _, req := range meta.Requires {
129			if err := validatePluginName(req.Name); err != nil {
130				return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
131			}
132			// A requirement's repo_url is author-controlled and reaches the git
133			// CLI during dependency planning — which runs before the install
134			// confirmation prompt. Reject non-URLs at the parse boundary.
135			if req.RepoURL != "" {
136				if err := validatePluginRepoURL(req.RepoURL); err != nil {
137					return nil, fmt.Errorf("%s declares invalid repo_url for requirement %q: %w", pluginMetadataFileName, req.Name, err)
138				}
139			}
140		}
141		return &meta, nil
142	}
143	
144	// PluginPkgDir returns the per-plugin package directory for the given bare
145	// name. Not created — callers use EnsurePluginPkgDir when writing.
146	func PluginPkgDir(name string) (string, error) {
147		if err := validatePluginName(name); err != nil {
148			return "", err
149		}
150		parent, err := pluginParentDir()
151		if err != nil {
152			return "", err
153		}
154		return filepath.Join(parent, pluginManagedPkgSubdir, name), nil
155	}
156	
157	// EnsurePluginPkgDir creates the package directory for name.
158	func EnsurePluginPkgDir(name string) (string, error) {
159		dir, err := PluginPkgDir(name)
160		if err != nil {
161			return "", err
162		}
163		if err := os.MkdirAll(dir, 0o750); err != nil {
164			return "", fmt.Errorf("create plugin pkg dir: %w", err)
165		}
166		return dir, nil
167	}
168	
169	// LoadPluginManifest reads the manifest for name. Returns (nil, nil) when
170	// the plugin has no manifest — local-dev installs and raw-PATH plugins.
171	func LoadPluginManifest(name string) (*PluginManifest, error) {
172		dir, err := PluginPkgDir(name)
173		if err != nil {
174			return nil, err
175		}
176		data, err := os.ReadFile(filepath.Join(dir, pluginManifestFileName)) //nolint:gosec // path is inside the managed pkg tree
177		if err != nil {
178			if errors.Is(err, os.ErrNotExist) {
179				return nil, nil //nolint:nilnil // no-manifest signal
180			}
181			return nil, fmt.Errorf("read plugin manifest: %w", err)
182		}
183		var m PluginManifest
184		if err := yaml.Unmarshal(data, &m); err != nil {
185			return nil, fmt.Errorf("parse plugin manifest for %q: %w", name, err)
186		}
187		return &m, nil
188	}
189	
190	// SavePluginManifest writes the manifest into the plugin's pkg dir.
191	func SavePluginManifest(m *PluginManifest) error {
192		dir, err := EnsurePluginPkgDir(m.Name)
193		if err != nil {
194			return err
195		}
196		data, err := yaml.Marshal(m)
197		if err != nil {
198			return fmt.Errorf("marshal plugin manifest: %w", err)
199		}
200		path := filepath.Join(dir, pluginManifestFileName)
201		if err := os.WriteFile(path, data, 0o644); err != nil { //nolint:gosec // manifest is non-secret provenance metadata
202			return fmt.Errorf("write plugin manifest: %w", err)
203		}
204		return nil
205	}
206	
207	// ListPluginManifests returns the manifests of every remote-installed
208	// plugin, sorted by name. Pkg entries without a readable manifest are
209	// skipped — a half-removed plugin shouldn't break listing.
210	func ListPluginManifests() ([]*PluginManifest, error) {
211		parent, err := pluginParentDir()
212		if err != nil {
213			return nil, err
214		}
215		entries, err := os.ReadDir(filepath.Join(parent, pluginManagedPkgSubdir))
216		if err != nil {
217			if errors.Is(err, os.ErrNotExist) {
218				return nil, nil
219			}
220			return nil, fmt.Errorf("read plugin pkg dir: %w", err)
221		}
222		var out []*PluginManifest
223		for _, e := range entries {
224			if !e.IsDir() {
225				continue
226			}
227			m, err := LoadPluginManifest(e.Name())
228			if err != nil || m == nil {
229				continue
230			}
231			out = append(out, m)
232		}
233		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
234		return out, nil
235	}
236	
237	// RemovePluginPkg deletes the plugin's pkg dir (binary + manifest).
238	// Missing dir is not an error — local-dev installs never had one.
239	func RemovePluginPkg(name string) error {
240		dir, err := PluginPkgDir(name)
241		if err != nil {
242			return err
243		}
